// Generates src/api/schema.d.ts from the OpenAPI contract. `--check` fails if the committed file is stale (CI).
import { readFileSync, writeFileSync } from 'node:fs'
import { pathToFileURL } from 'node:url'

import openapiTS, { astToString } from 'openapi-typescript'

const SOURCE = 'openapi/waystation-m0.yaml'
const TARGET = 'src/api/schema.d.ts'
const HEADER = `// SPDX-License-Identifier: GPL-3.0-or-later
// Generated by \`make gen-api\` from ${SOURCE}. Do not edit by hand.

`

const ast = await openapiTS(pathToFileURL(SOURCE), { alphabetize: false, immutable: false })
const output = HEADER + astToString(ast)

if (process.argv.includes('--check')) {
  let current = ''
  try {
    current = readFileSync(TARGET, 'utf8')
  } catch {
    // Missing counts as stale.
  }
  if (current !== output) {
    console.error(`${TARGET} is stale: run \`make gen-api\` and commit the result.`)
    process.exit(1)
  }
  console.log(`${TARGET} is up to date.`)
} else {
  writeFileSync(TARGET, output)
  console.log(`Wrote ${TARGET}`)
}
